window._computeAdherence = function() {
const data = window.PRONOSTICS_DATA;
if (!data || !data.days) return null;
const bets = _loadUserBets();
if (!bets.length) return { adherence: null, modelPicksCount: 0, userBetsCount: 0, missed: [] };
const userMatchIds = new Set(bets.map(b => String(b.matchId)));
const cutoff = Date.now() - 30 * 24 * 3600 * 1000;
const strongModelPicks = [];
Object.values(data.days || {}).forEach(arr => (arr || []).forEach(m => {
const ts = new Date(m.date).getTime();
if (!isFinite(ts) || ts < cutoff) return;
try {
const pred = predictMatch(m);
if (!pred || !pred.pick || pred.skip || pred.lowConf) return;
const rel = pred.reliability ?? pred.pick.prob ?? 0;
if (rel < 0.65) return;  // pas un strong pick
strongModelPicks.push({ id: String(m.id), name: m.name, ts });
} catch(e) { swallowError(e); }
}));
if (!strongModelPicks.length) return { adherence: null, modelPicksCount: 0, userBetsCount: bets.length, missed: [] };
const followed = strongModelPicks.filter(p => userMatchIds.has(p.id)).length;
const adherence = followed / strongModelPicks.length;
const missed = strongModelPicks.filter(p => !userMatchIds.has(p.id)).slice(0, 5);
return {
adherence,
modelPicksCount: strongModelPicks.length,
userBetsCount: bets.length,
followed,
missed,
};
};
window._userBetsStats = function() {
const bets = _loadUserBets().filter(b => b.settled && b.result !== 'void');
if (!bets.length) return null;
const wins = bets.filter(b => b.result === 'won').length;
const losses = bets.filter(b => b.result === 'lost').length;
const totalStake = bets.reduce((a, b) => a + (b.stake || 0), 0);
const totalPnL = bets.reduce((a, b) => a + (b.pnl || 0), 0);
let curStreak = 0, lastResult = null;
let maxWinStreak = 0, maxLossStreak = 0;
let curWin = 0, curLoss = 0;
const sortedByTs = bets.slice().sort((a, b) => (a.settledTs || 0) - (b.settledTs || 0));
sortedByTs.forEach(b => {
if (b.result === 'won') {
curWin++;
curLoss = 0;
maxWinStreak = Math.max(maxWinStreak, curWin);
} else if (b.result === 'lost') {
curLoss++;
curWin = 0;
maxLossStreak = Math.max(maxLossStreak, curLoss);
}
});
const recent = sortedByTs.slice().reverse();
if (recent.length) {
const cur = recent[0].result;
curStreak = 1;
for (let i = 1; i < recent.length; i++) {
if (recent[i].result === cur) curStreak++;
else break;
}
lastResult = cur;
}
const bySport = {};
bets.forEach(b => {
const sp = b.sport || 'unknown';
if (!bySport[sp]) bySport[sp] = { n: 0, wins: 0, stake: 0, pnl: 0 };
bySport[sp].n++;
if (b.result === 'won') bySport[sp].wins++;
bySport[sp].stake += (b.stake || 0);
bySport[sp].pnl += (b.pnl || 0);
});
const byMarket = {};
bets.forEach(b => {
const mk = b.market || '1n2';
if (!byMarket[mk]) byMarket[mk] = { n: 0, wins: 0, stake: 0, pnl: 0 };
byMarket[mk].n++;
if (b.result === 'won') byMarket[mk].wins++;
byMarket[mk].stake += (b.stake || 0);
byMarket[mk].pnl += (b.pnl || 0);
});
Object.values(bySport).forEach(s => {
s.winRate = s.n > 0 ? s.wins / s.n : 0;
s.roi = s.stake > 0 ? s.pnl / s.stake : 0;
});
Object.values(byMarket).forEach(s => {
s.winRate = s.n > 0 ? s.wins / s.n : 0;
s.roi = s.stake > 0 ? s.pnl / s.stake : 0;
});
return {
n: bets.length,
wins, losses,
winRate: wins / bets.length,
totalStake: Math.round(totalStake * 100) / 100,
totalPnL: Math.round(totalPnL * 100) / 100,
roi: totalStake > 0 ? totalPnL / totalStake : 0,
maxWinStreak,
maxLossStreak,
currentStreak: curStreak,
currentStreakSide: lastResult,
bySport,
byMarket,
avgStake: bets.length > 0 ? totalStake / bets.length : 0,
avgPnL: bets.length > 0 ? totalPnL / bets.length : 0,
};
};
window._detectUserTilt = function() {
const bets = _loadUserBets()
.filter(b => b && b.settled && b.result !== 'void')
.sort((a, b) => Number(a.settledTs || a.ts || 0) - Number(b.settledTs || b.ts || 0));
if (bets.length < 3) {
return { level: 'learning', title: 'Discipline en apprentissage', message: 'Tracke encore quelques paris pour détecter les séries à risque.', lossStreak: 0, stakeTrend: 0 };
}
const recent = bets.slice().reverse();
let lossStreak = 0;
for (const b of recent) {
if (b.result === 'lost') lossStreak++;
else break;
}
let winStreak = 0;
for (const b of recent) {
if (b.result === 'won') winStreak++;
else break;
}
const last3 = recent.slice(0, 3);
const prev3 = recent.slice(3, 6);
const avgStake = rows => {
const valid = rows.map(b => Number(b.stake || 0)).filter(v => v > 0);
return valid.length ? valid.reduce((a, v) => a + v, 0) / valid.length : 0;
};
const lastAvg = avgStake(last3);
const prevAvg = avgStake(prev3);
const stakeTrend = prevAvg > 0 ? (lastAvg - prevAvg) / prevAvg : 0;
const recentStakeLift = Number(last3[2]?.stake || 0) > 0
? (Number(last3[0]?.stake || 0) - Number(last3[2]?.stake || 0)) / Number(last3[2]?.stake || 1)
: 0;
const stakesIncreasing = last3.length === 3
&& last3.every(b => b.result === 'lost')
&& Number(last3[0].stake || 0) >= Number(last3[1].stake || 0)
&& Number(last3[1].stake || 0) >= Number(last3[2].stake || 0)
&& (stakeTrend >= 0.15 || recentStakeLift >= 0.15);
if (lossStreak >= 5 || (lossStreak >= 3 && stakesIncreasing)) {
return {
level: 'danger',
title: 'Pause recommandée',
message: `${lossStreak} pertes d'affilée${stakesIncreasing ? ' et mises en hausse' : ''}. Stop 24h ou mise divisée par 2 : pas de revanche contre la variance.`,
lossStreak,
winStreak,
stakeTrend,
cooldownHours: 24,
};
}
if (lossStreak >= 3) {
return {
level: 'warn',
title: 'Zone de tilt',
message: `${lossStreak} pertes d'affilée. Garde les mises fixes et évite d'augmenter pour te refaire.`,
lossStreak,
winStreak,
stakeTrend,
cooldownHours: 12,
};
}
if (winStreak >= 5 && stakeTrend > 0.25) {
return {
level: 'warn',
title: 'Euphorie à contrôler',
message: `${winStreak} gains d'affilée avec mises qui montent. Ne dépasse pas le Kelly conseillé : la série ne garantit rien.`,
lossStreak,
winStreak,
stakeTrend,
cooldownHours: 0,
};
}
return {
level: 'ok',
title: 'Discipline stable',
message: 'Pas de signal de tilt détecté sur tes derniers paris suivis.',
lossStreak,
winStreak,
stakeTrend,
cooldownHours: 0,
};
};
window._userBetsPnlCalendar = function(daysBack = 365) {
const isoParis = (d) => {
try { return d.toLocaleDateString('fr-CA', { timeZone: 'Europe/Paris' }); }
catch(e) { return d.toISOString().slice(0, 10); }
};
const todayIso = isoParis(new Date());
const start = new Date(todayIso + 'T00:00:00Z');
start.setUTCDate(start.getUTCDate() - Math.max(30, Number(daysBack) || 365) + 1);
const startIso = start.toISOString().slice(0, 10);
const cells = new Map();
const bets = _loadUserBets()
.filter(b => b && b.settled && b.result !== 'void')
.sort((a, b) => Number(a.settledTs || a.ts || 0) - Number(b.settledTs || b.ts || 0));
bets.forEach(b => {
const ts = Number(b.settledTs || b.ts || 0);
if (!isFinite(ts) || ts <= 0) return;
const key = isoParis(new Date(ts));
if (key < startIso || key > todayIso) return;
const c = cells.get(key) || { date: key, bets: 0, won: 0, lost: 0, stake: 0, pnl: 0 };
c.bets++;
c.stake += Number(b.stake || 0);
c.pnl += Number(b.pnl || (b.result === 'won' ? Number(b.stake || 0) * (Number(b.odd || 1) - 1) : -Number(b.stake || 0)));
if (b.result === 'won') c.won++;
if (b.result === 'lost') c.lost++;
cells.set(key, c);
});
const active = [...cells.values()];
const totalStake = active.reduce((a, c) => a + c.stake, 0);
const totalPnl = active.reduce((a, c) => a + c.pnl, 0);
const positiveDays = active.filter(c => c.pnl > 0).length;
const negativeDays = active.filter(c => c.pnl < 0).length;
const bestDay = active.slice().sort((a, b) => b.pnl - a.pnl)[0] || null;
const worstDay = active.slice().sort((a, b) => a.pnl - b.pnl)[0] || null;
return {
startIso,
todayIso,
daysBack: Math.max(30, Number(daysBack) || 365),
bets: bets.length,
activeDays: active.length,
positiveDays,
negativeDays,
totalStake,
totalPnl,
roi: totalStake > 0 ? totalPnl / totalStake : 0,
bestDay,
worstDay,
cells,
};
};
window._bankrollGrowthProjection = function(initialBankroll = 1000) {
const stats = typeof window._userBetsStats === 'function' ? window._userBetsStats() : null;
const cal = typeof window._userBetsPnlCalendar === 'function' ? window._userBetsPnlCalendar(365) : null;
const sample = Number(stats?.n || 0);
const observedRoi = isFinite(Number(stats?.roi)) ? Number(stats.roi) : 0.04;
const trustedRoi = sample >= 20 ? observedRoi : sample >= 8 ? observedRoi * 0.65 + 0.02 : 0.035;
const betsPerDay = cal && cal.activeDays ? Math.max(0.5, Math.min(8, cal.bets / cal.activeDays)) : 3;
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
const baseRoi = clamp(trustedRoi, -0.12, 0.18);
const start = Math.max(10, Number(initialBankroll) || 1000);
const scenarios = [
{ key: 'prudente', name: 'Prudente', stakePct: 0.006, roi: baseRoi * 0.70, note: 'mises fixes, seulement tiers fiables' },
{ key: 'equilibree', name: 'Équilibrée', stakePct: 0.010, roi: baseRoi, note: 'rythme normal, Kelly fractionné' },
{ key: 'agressive', name: 'Agressive', stakePct: 0.016, roi: baseRoi * 1.12, note: 'plus volatile, drawdown plus probable' },
];
const horizons = [30, 90, 365];
const project = (sc, days) => {
const dailyReturn = clamp(sc.stakePct * betsPerDay * sc.roi, -0.025, 0.035);
const end = start * Math.pow(1 + dailyReturn, days);
return { days, end, delta: end - start, pct: (end / start - 1), dailyReturn };
};
return {
start,
sample,
observedRoi,
trustedRoi,
betsPerDay,
horizons,
scenarios: scenarios.map(sc => ({
...sc,
projections: horizons.map(days => project(sc, days)),
series90: Array.from({ length: 91 }, (_, i) => project(sc, i).end),
})),
};
};
window._computeIfYouHadFollowed = function() {
const data = window.PRONOSTICS_DATA;
if (!data || !data.days) return null;
const userBets = _loadUserBets();
const userBetIds = new Set(userBets.map(b => String(b.matchId)));
let n = 0, modelWins = 0, modelStakeTotal = 0, modelPnL = 0, missedWins = 0, missedPnL = 0;
Object.values(data.days || {}).forEach(arr => (arr || []).forEach(m => {
if (!m.completed) return;
try {
const pred = predictMatch(m);
if (!pred || !pred.pick || pred.skip || !pred.isLock) return;  // strong picks only
const res = evaluateModelPick(m, pred);
if (res !== 'won' && res !== 'lost') return;
const odd = pred.odds && (pred.pick.key === '1' ? pred.odds.home : pred.pick.key === '2' ? pred.odds.away : pred.odds.draw);
if (!odd) return;
const stake = 1;  // unit stake
const pnl = res === 'won' ? stake * (odd - 1) : -stake;
n++;
modelStakeTotal += stake;
modelPnL += pnl;
if (res === 'won') modelWins++;
if (!userBetIds.has(String(m.id))) {
if (res === 'won') {
missedWins++;
missedPnL += stake * (odd - 1);
} else {
missedPnL -= stake;
}
}
} catch(e) { swallowError(e); }
}));
return {
n,
modelWinRate: n > 0 ? modelWins / n : 0,
modelROI: modelStakeTotal > 0 ? modelPnL / modelStakeTotal : 0,
modelPnL: Math.round(modelPnL * 100) / 100,
missedWins,
missedPnL: Math.round(missedPnL * 100) / 100,
};
};
window._smartKelly = function(rel, odd, bankroll = 50) {
if (!isFinite(rel) || !isFinite(odd) || odd <= 1 || rel <= 0 || rel >= 1) return 0;
const baseKelly = (rel * odd - 1) / (odd - 1);
if (baseKelly <= 0) return 0;
let multiplier = 0.25;
if (rel >= 0.70) multiplier = 0.50;
else if (rel < 0.55) multiplier = 0.10;
const stake = bankroll * baseKelly * multiplier;
const cap = bankroll * 0.10;
return Math.max(0.10, Math.min(stake, cap));
};

function computeOddsDrift(match, pred, best) {
if (!match || !pred || !best) return null;
const snap = match.odds_snapshot;
if (!snap) return null;
const pickKey = best.key || pred.pick.key;
let snapOdd = null;
if (best.market === '1n2' || !best.market) {
if (pickKey === '1') snapOdd = snap.home;
else if (pickKey === '2') snapOdd = snap.away;
else if (pickKey === 'X') snapOdd = snap.draw;
} else if (snap.markets) {
const mk = snap.markets[best.market];
if (mk) {
if (best.market === 'ou25' || best.market === 'ou15' || best.market === 'ou35') {
snapOdd = pickKey?.startsWith('O') ? mk.over : mk.under;
} else if (best.market === 'btts') {
snapOdd = pickKey === 'BTTS_Y' ? mk.yes : mk.no;
}
}
}
if (!(snapOdd > 1)) return null;
const currentOdd = best.odd;
const drift = currentOdd - snapOdd;
const driftPct = drift / snapOdd;
let status, label, color;
if (Math.abs(driftPct) < 0.02) {
status = 'stable';
label = 'Cote stable';
color = 'var(--text-dim)';
} else if (driftPct >= 0.05) {
status = 'better';
label = `Cote a monté +${(driftPct*100).toFixed(0)}% (encore plus de value)`;
color = 'var(--accent)';
} else if (driftPct >= 0.02) {
status = 'slight_better';
label = `Cote +${(driftPct*100).toFixed(0)}% (légèrement mieux)`;
color = 'var(--accent)';
} else if (driftPct <= -0.10) {
status = 'skip';
label = `Cote a chuté ${(driftPct*100).toFixed(0)}% — marché s'est ajusté, value perdue`;
color = 'var(--danger)';
} else if (driftPct <= -0.05) {
status = 'caution';
label = `Cote ${(driftPct*100).toFixed(0)}% — value réduite, mise prudente`;
color = 'var(--warn)';
} else {
status = 'slight_worse';
label = `Cote ${(driftPct*100).toFixed(0)}% (légèrement moins)`;
color = 'var(--text-dim)';
}
const newEdge = (pred.reliability ?? pred.pick?.prob ?? 0) - 1 / currentOdd;
return { drift, driftPct, status, label, color, snapOdd, currentOdd, newEdge };
}
try { window.computeOddsDrift = computeOddsDrift; } catch(e) { swallowError(e); }

function computeAdvancedMetrics() {
const data = window.PRONOSTICS_DATA;
if (!data || !data.days) return null;
const settled = [];
Object.values(data.days || {}).forEach(arr => (arr || []).forEach(m => {
if (!m.completed) return;
try {
const pred = predictMatch(m);
if (!pred || !pred.pick) return;
const res = (typeof evaluateModelPick === 'function') ? evaluateModelPick(m, pred) : null;
if (res !== 'won' && res !== 'lost') return;
const pickKey = pred.pick.key;
const odd = pred.odds && (pickKey === '1' ? pred.odds.home : pickKey === '2' ? pred.odds.away : pred.odds.draw);
if (!(odd > 1)) return;
const pnl = res === 'won' ? (Number(odd) - 1) : -1;  // 1u flat stake
settled.push({ ts: new Date(m.date).getTime(), result: res, pnl });
} catch(e) { swallowError(e); }
}));
if (!settled.length) return null;
settled.sort((a, b) => a.ts - b.ts);  // chrono ascending
let cumPnL = 0, peak = 0, maxDD = 0, curDD = 0;
settled.forEach(s => {
cumPnL += s.pnl;
if (cumPnL > peak) peak = cumPnL;
curDD = peak - cumPnL;
if (curDD > maxDD) maxDD = curDD;
});
let curWinStreak = 0, maxWinStreak = 0, curLossStreak = 0, maxLossStreak = 0;
settled.forEach(s => {
if (s.result === 'won') {
curWinStreak++; curLossStreak = 0;
if (curWinStreak > maxWinStreak) maxWinStreak = curWinStreak;
} else {
curLossStreak++; curWinStreak = 0;
if (curLossStreak > maxLossStreak) maxLossStreak = curLossStreak;
}
});
const n = settled.length;
const meanPnL = settled.reduce((a, s) => a + s.pnl, 0) / n;
const variance = settled.reduce((a, s) => a + Math.pow(s.pnl - meanPnL, 2), 0) / n;
const stdev = Math.sqrt(variance);
const sharpe = stdev > 0 ? meanPnL / stdev : null;
const maxDDPct = peak >= 1 ? Math.min(1, maxDD / peak) : null;
return {
n, finalPnL: cumPnL, maxDrawdown: maxDD, maxDDPct,
maxWinStreak, maxLossStreak,
sharpe, meanPnL, stdev,
};
}
try { window.computeAdvancedMetrics = computeAdvancedMetrics; } catch(e) { swallowError(e); }

function detectStreaks() {
const data = window.PRONOSTICS_DATA;
if (!data || !data.days) return { streakWins: 0, streakLosses: 0, alert: null };
const settled = [];
Object.values(data.days || {}).forEach(arr => (arr || []).forEach(m => {
if (!m.completed) return;
try {
const pred = predictMatch(m);
if (!pred || !pred.pick) return;
const res = (typeof evaluateModelPick === 'function') ? evaluateModelPick(m, pred) : null;
if (res !== 'won' && res !== 'lost') return;
settled.push({ ts: new Date(m.date).getTime(), result: res, name: m.name });
} catch(e) { swallowError(e); }
}));
settled.sort((a, b) => b.ts - a.ts);
if (!settled.length) return { streakWins: 0, streakLosses: 0, alert: null };
const currentSide = settled[0].result;
let streak = 0;
for (const s of settled) {
if (s.result === currentSide) streak++;
else break;
}
const streakWins = currentSide === 'won' ? streak : 0;
const streakLosses = currentSide === 'lost' ? streak : 0;
const last10 = settled.slice(0, 10);
const last10Wins = last10.filter(s => s.result === 'won').length;
let alert = null;
if (streakLosses >= 5) {
alert = {
level: 'danger',
msg: `⛔ ${streakLosses} paris perdants d'affilée. Le modèle traverse une variance négative — STOP recommandé pendant 24h, ou réduis Kelly à 0.10 max.`,
};
} else if (streakLosses >= 3) {
alert = {
level: 'warn',
msg: `⚠ ${streakLosses} paris perdants récents. Respecte le Kelly fractionné — ne mise pas plus pour "te refaire". C'est ainsi que tu casses ta bankroll.`,
};
} else if (streakWins >= 7) {
alert = {
level: 'warn',
msg: `🏆 ${streakWins} paris gagnants d'affilée — bravo. Mais attention au gambler's fallacy : ne pousse PAS Kelly au-delà du suggéré, la variance va finir par te rattraper.`,
};
} else if (last10.length >= 8 && last10Wins / last10.length < 0.3) {
alert = {
level: 'warn',
msg: `📉 Seulement ${last10Wins}/${last10.length} gagnants sur les 10 derniers. Recalibre tes filtres : essaie EV+ ≥ 5% ou désactive les ligues mineures.`,
};
}
return { streakWins, streakLosses, currentSide, settledCount: settled.length, last10Wins, alert };
}
try { window.detectStreaks = detectStreaks; } catch(e) { swallowError(e); }

const RISK_LIMITS_KEY = 'riskLimits';
