const wH = parseInt(String(recH).split('-')[0], 10) || 0;
const wA = parseInt(String(recA).split('-')[0], 10) || 0;
if (wH > 30 || wA > 30) score += 12;
else if (wH > 20 || wA > 20) score += 8;
