// AUDIT 2026-05-09 v47.1 — A/B test framework léger.
// Permet de tester variants côté frontend (ex: "verdict_threshold_22" vs
// "verdict_threshold_18", "card_layout_v1" vs "card_layout_v2") en
// assignant aléatoirement un variant stable par user (localStorage),
// puis en logant les outcomes via _ab.track(experiment, outcome).
window._ab = {
  // Get variant for an experiment (50/50 split by default)
  variant(experiment, weights = { A: 0.5, B: 0.5 }) {
    try {
      const key = `paris_sportif_ab_${experiment}`;
      let v = localStorage.getItem(key);
      if (!v) {
        const r = Math.random();
        let cum = 0;
        for (const [name, w] of Object.entries(weights)) {
          cum += w;
          if (r < cum) { v = name; break; }
        }
        v = v || 'A';
        localStorage.setItem(key, v);
      }
      return v;
    } catch (e) { return 'A'; }
  },
  // Log an outcome for an experiment+variant (ex: bet won/lost, click, etc.)
  track(experiment, outcome, metadata = {}) {
    try {
      const key = 'paris_sportif_ab_events_v1';
      const raw = localStorage.getItem(key);
      const arr = raw ? JSON.parse(raw) : [];
      arr.push({
        ts: Date.now(),
        experiment,
        variant: window._ab.variant(experiment),
        outcome,
        metadata
      });
      // Ring buffer 500 events
      if (arr.length > 500) arr.splice(0, arr.length - 500);
      localStorage.setItem(key, JSON.stringify(arr));
    } catch (e) {}
  },
  // Get summary stats for an experiment
  stats(experiment) {
    try {
      const events = JSON.parse(localStorage.getItem('paris_sportif_ab_events_v1') || '[]');
      const filtered = events.filter(e => e.experiment === experiment);
      const byVariant = {};
      filtered.forEach(e => {
        const v = e.variant || 'A';
        if (!byVariant[v]) byVariant[v] = { n: 0, outcomes: {} };
        byVariant[v].n++;
        byVariant[v].outcomes[e.outcome] = (byVariant[v].outcomes[e.outcome] || 0) + 1;
      });
      return { experiment, total: filtered.length, byVariant };
    } catch (e) { return { error: e.message }; }
  }
};

window._v45RecommendedStake = (bankroll, rel, odd) => {
  if (window._v45StakeMode() === 'kelly') {
    if (typeof window.kellyFraction === 'function') {
      const k = window.kellyFraction(rel, odd, 0.25);
      const cap = (Number(bankroll) || 100) * 0.10;
      const stake = Math.min(cap, (Number(bankroll) || 100) * k);
      return Math.max(1, Math.round(stake));
    }
  }
  return window._v45FlatStake(bankroll);
};

// AUDIT 2026-05-08 v39 — Recommandation finale unifiée.
// User : "il me faut UN SEUL indicateur qui me dit si je peux miser
// dessus ou pas". Combine cote validation + confiance + edge + score
// d'opportunité + tier + segment trust historique en un verdict :
// 'bet' (miser) / 'bet-light' (mise prudente) / 'watch' (surveiller) /
// 'check' (cote à vérifier) / 'skip' (passer).
const _v39FinalRec = (p) => {
  if (!p || !p.m) return { verdict: 'skip', label: 'Passer', score: 0, tone: 'red', reason: '' };
  const oddMeta = p.oddValidation || (typeof validatePickOdd === 'function' ? validatePickOdd(p.m, p.best || p, p.pred) : null);
  const oddOk = typeof v38OddTopEligible === 'function' ? v38OddTopEligible(oddMeta) : true;
  const rel = Number(p.rel || 0);
  const edge = Number(p.edge || 0);
  const opp = Number(p.opportunity || 0);
  const oddNum = Number(p.odd || 0);
  const tier = String(p.tier || 'lowconf');
  const trust = (typeof window._v37PickSegmentTrust === 'function') ? window._v37PickSegmentTrust(p.m, p.best || p) : null;
  const trustTier = trust?.tier || 'uncertain';
  const fmtPct = (n) => (n >= 0 ? '+' : '') + (n * 100).toFixed(1) + 'pt';
  if (p.forceMicroBet && edge > 0 && oddNum >= 1.30 && oddNum <= 10.00) {
    const note = oddOk ? 'cote Winamax exacte' : 'cote à confirmer manuellement';
    return { verdict: 'bet-light', label: 'Micro mise', score: Math.max(18, opp), tone: 'green-light', reason: `Plancher autonomie 30/jour · ${note} · Edge ${fmtPct(edge)} positif` };
  }
  // Veto 1 : cote non validée → "Cote à vérifier" (n'apparaît normalement pas
  // dans le dashboard car filtre upstream, mais safety net).
  if (!oddOk) {
    return { verdict: 'check', label: 'À revérifier', score: Math.min(40, opp), tone: 'amber', reason: 'Cote Winamax non confirmée — refuser ou re-vérifier' };
  }
  // AUDIT 2026-05-08 v40.4 — Veto segment assoupli.
  // Avant : 'low' (ROI < -5% sur ≥10 paris) → AUTO "À éviter", 'warn' → AUTO
  // "Prudent". Conséquence : 4/5 picks Demain "À éviter" parce que la segment
  // BTTS-no foot fait -7.7% sur 69 paris. L'user n'a rien à parier.
  // Maintenant : segment perdant n'est un VETO que si très grave (ROI < -10%
  // ET n ≥ 30) OU si le pick est faible par ailleurs (opp < 60). Sinon on
  // laisse passer le verdict normal et on warn via le badge segment trust.
  const trustRoiPct = Number(trust?.roi_pct || 0);
  const trustN = Number(trust?.n || 0);
  // AUDIT 2026-05-08 v40.8 — OUTSIDER OVERRIDE.
  // Backtest officiel (backtest_report_v2.json) prouve que tier='out' (cote ≥5,
  // edge ≥5pt) fait +183.5% ROI sur 356 paris (la stratégie #1 du site).
  // À l'inverse, safe/solid/value perdent -14% à -19%. Le verdict doit
  // refléter cette vérité statistique : un Outsider qualifié = MISER auto,
  // peu importe le segment trust (qui est calculé sur sub-segments plus petits
  // et moins fiables que le tier global).
  const isOutsiderQualified = (tier === 'out' || (oddNum >= 5 && edge >= 0.05));
  if (isOutsiderQualified) {
    return { verdict: 'bet', label: 'Miser (Outsider 💎)', score: Math.max(80, opp), tone: 'green', reason: `Outsider rentable historiquement (+183% ROI sur 356 paris) · Conf ${(rel*100).toFixed(0)}% · Edge ${fmtPct(edge)}` };
  }
  // AUDIT 2026-05-09 v43.4 — VALUE OVERRIDE.
  // Backtest officiel (backtest_strategies.json leaderboard) prouve que
  // value_only (edge ≥ 5pt) fait +33.1% ROI sur 1251 paris (max_dd 3.5%).
  // C'est la 2e stratégie la + profitable. Donc tout pick edge ≥ 5pt avec
  // rel ≥ 0.40 (filtre minimal de qualité) doit être promu Miser auto.
  // User feedback : "ont passe a coté de paris qui passe facilement" — c'est
  // exactement ces value picks que les seuils opp masquaient.
  if (edge >= 0.05 && rel >= 0.40 && oddNum >= 1.40) {
    const seg = (trustTier === 'low' || trustTier === 'warn') ? ` ⚠ segment ${trustRoiPct.toFixed(1)}%` : '';
    return { verdict: 'bet', label: 'Miser (Value 🎯)', score: Math.max(70, opp), tone: 'green', reason: `Value rentable historiquement (+33% ROI sur 1251 paris) · Conf ${(rel*100).toFixed(0)}% · Edge ${fmtPct(edge)}${seg}` };
  }
  // v46.2 — NET EDGE veto : edge brut MINUS segment ROI négatif < +1pt → skip.
  // User feedback : "edge +3.2pt - segment -3.8% = -0.6pt net mais pick
  // recommandé". Maintenant on calcule le NET espéré et on skip si négatif.
  if (trustTier === 'low' && trustN >= 30) {
    const edgePt = edge * 100;
    const segmentPt = trustRoiPct;  // déjà en %
    const netEdgePt = edgePt + segmentPt; // segment négatif → net réduit
    if (netEdgePt < 1) {
      return { verdict: 'skip', label: 'À éviter (net ⚠)', score: Math.min(30, opp), tone: 'red', reason: `Edge brut +${edgePt.toFixed(1)}pt - segment ${segmentPt.toFixed(1)}% = net ${netEdgePt >= 0 ? '+' : ''}${netEdgePt.toFixed(1)}pt (insuffisant)` };
    }
  }
  // v46.1 — Veto durci : retour -10%/n30 (Chinese League etc.).
  const segmentSeverelyBad = trustTier === 'low' && trustRoiPct < -10 && trustN >= 30;
  if (segmentSeverelyBad) {
    return { verdict: 'skip', label: 'À éviter', score: Math.min(35, opp), tone: 'red', reason: `Historique segment ${trustRoiPct.toFixed(1)}% sur ${trustN} paris (très défavorable)` };
  }
  // v46.1 — Warning fort si segment moyen-bad (-7% à -10%) sur grand sample
  const segmentMediumBad = trustTier === 'low' && trustRoiPct < -7 && trustN >= 50;
  if (segmentMediumBad) {
    return { verdict: 'watch', label: 'Surveiller (segment ⚠)', score: Math.min(40, opp), tone: 'orange', reason: `Edge OK mais segment ${trustRoiPct.toFixed(1)}% sur ${trustN} paris — preuve historique négative` };
  }
  // AUDIT 2026-05-08 v40.5 — Seuils baissés pour refléter la réalité du
  // modèle (Brier 0.231, ROI 0%). Avant : 'Miser' >= 75, jamais atteint.
  // Maintenant : 'Miser' >= 60, 'Petite mise' >= 45, 'Surveiller' >= 30.
  // v43.4 baisse encore : 60→50 / 32→22 / 25→14. User want 15-30 picks/jour.
  // Strong positive : tier safe/lock + opp >= 50 → MISER même si segment warn.
  if ((tier === 'safe' || tier === 'lock') && opp >= 45) {
    const seg = (trustTier === 'low' || trustTier === 'warn') ? ` ⚠ segment ${trustRoiPct.toFixed(1)}%` : '';
    return { verdict: 'bet', label: 'Miser', score: opp, tone: 'green', reason: `Conf ${(rel*100).toFixed(0)}% · Edge ${fmtPct(edge)}${seg}` };
  }
  // Strong : opp >= 50 (peu importe segment, sauf veto severe ci-dessus).
  if (opp >= 50) {
    const seg = (trustTier === 'low' || trustTier === 'warn') ? ` ⚠ segment ${trustRoiPct.toFixed(1)}%` : '';
    return { verdict: 'bet', label: 'Miser', score: opp, tone: 'green', reason: `Conf ${(rel*100).toFixed(0)}% · Edge ${fmtPct(edge)}${seg}` };
  }
  // v43.4 — Petite mise seuil 32→22, et ne plus downgrade auto vers watch
  // pour low trust (juste warn dans le label).
  if (opp >= 22) {
    const seg = (trustTier === 'low' || trustTier === 'warn') ? ` ⚠ segment ${trustRoiPct.toFixed(1)}%` : '';
    return { verdict: 'bet-light', label: 'Petite mise', score: opp, tone: 'green-light', reason: `Conf ${(rel*100).toFixed(0)}% · Edge ${fmtPct(edge)}${seg}` };
  }
  // v43.4 — Edge bridge : si edge ≥ 2.5pt même opp faible → bet-light.
  // Sinon Surveiller jusqu'à opp 14, sinon skip.
  if (edge >= 0.025 && rel >= 0.45 && oddNum >= 1.30) {
    return { verdict: 'bet-light', label: 'Petite mise', score: Math.max(25, opp), tone: 'green-light', reason: `Edge ${fmtPct(edge)} positif · Conf ${(rel*100).toFixed(0)}%` };
  }
  // v55.2 — Autonomie volume : quand la cote Winamax est exacte et que
  // l'edge reste positif, on garde une micro mise au lieu de basculer en veille.
  // Cela évite les jours "courts" où le tableau montre 30 lignes mais trop peu
  // de vrais boutons Miser.
  if (edge > 0 && oddNum >= 1.30 && oddNum <= 10.00) {
    const seg = (trustTier === 'low' || trustTier === 'warn') ? ` ⚠ segment ${trustRoiPct.toFixed(1)}%` : '';
    return { verdict: 'bet-light', label: 'Micro mise', score: Math.max(18, opp), tone: 'green-light', reason: `Cote Winamax exacte · Edge ${fmtPct(edge)} positif · mise réduite${seg}` };
  }
  if (opp >= 14) {
    return { verdict: 'watch', label: 'Surveiller', score: opp, tone: 'orange', reason: 'Edge moyen — décide après modal' };
  }
  return { verdict: 'skip', label: 'Passer', score: opp, tone: 'red', reason: 'Pas assez de signal' };
};
