const todayISOStr = new Date().toLocaleDateString('fr-CA', { timeZone: 'Europe/Paris' });
const backtestDateDefault = walletBacktestDateEff || '';
const backtestIsDefault = (_walletBacktestStart === 10 && !_walletBacktestDate);
